declare(strict_types=1);

namespace murdermystery\gamemodes\infection;

use murdermystery\gamemodes\infection\tasks\MatchTimeInfectionTask;
use murdermystery\gamemodes\MMArena;
use murdermystery\MurderMystery;
use murdermystery\utils\Items;
use murdermystery\utils\MMChance;
use NetherGames\NGEssentials\utils\CustomIcon;
use pocketmine\entity\Skin;
use pocketmine\player\Player;
use pocketmine\utils\TextFormat;
use function array_diff;
use function base64_decode;
use function count;
use function in_array;

class MMArenaInfection extends MMArena
{
    /** @var Player[] */
    private array $infected = [];
    /** @var int */
    private int $alphaDeaths = 0;

    /** @var array */
    private array $kills = [];
    /** @var array */
    private array $skinData = [];

    public function __construct(MurderMystery $plugin, int $modeId, int $id, bool $privateGame)
    {
        parent::__construct($plugin, $modeId, $id, $privateGame);

        $this->listener = new InfectionArenaListener($this);
    }

    public function addInfected(Player $player): void
    {
        $this->infected[] = $player;
    }

    public function addKill(Player $player): void
    {
        $this->kills[$player->getName()]++;

        $this->getScoreboard()->setLine([$player], 5, CustomIcon::KILLS . TextFormat::GREEN . $this->getKills($player));
    }

    public function getKills(Player $player): int
    {
        return $this->kills[$player->getName()];
    }

    public function addAlphaDeath(): void
    {
        $this->alphaDeaths++;
    }

    public function getAlphaDeaths(): int
    {
        return $this->alphaDeaths;
    }

    public function canRespawn(): bool
    {
        return !($this->alphaDeaths >= 2 || $this->getAlpha() === null);
    }

    public function getAlpha(): ?Player
    {
        return $this->infected[0] ?? null;
    }

    public function queuePlayer(Player $player): void
    {
        $this->kills[$player->getName()] = 0;
        $this->skinData[$player->getName()] = $player->getSkin();

        parent::queuePlayer($player);
    }

    public function startGame(): void
    {
        $array = [];

        $array[14] = '';
        $array[13] = CustomIcon::GAMEMODE . ':' . TextFormat::GREEN . 'Survivor';
        $array[12] = '';
        $array[11] = CustomIcon::HOURGLASS . TextFormat::GREEN . '5:00';
        $array[10] = '';
        $array[9] = CustomIcon::STEVE_HEAD . TextFormat::GREEN . count($this->getPlayers());
        $array[8] = CustomIcon::ZOMBIE_HEAD . TextFormat::RED . 0;
        $array[7] = '';
        $array[6] = CustomIcon::ALEX_HEAD . TextFormat::GREEN . 'Alive';
        $array[5] = CustomIcon::KILLS . TextFormat::GREEN . 0;
        $array[4] = '';
        $array[3] = CustomIcon::MAP . TextFormat::GREEN . $this->getMapDisplayName();
        $array[2] = '';
        $array[1] = CustomIcon::NETHERGAMES . TextFormat::GOLD . 'ngmc.co';

        $this->getScoreboard()->setLines($this->getPlayers(), $array);

        foreach ($this->getPlayers() as $player) {
            if (!$this->isSpectator($player)) {
                $player->setNameTag(''); //TODO: Remove when MCPE fix that
            }

            if ($this->isInfected($player) && $this->getGameSettings()->hasAlwaysCompass()) {
                $player->getInventory()->setItem(Items::COMPASS, Items::getInnocentLocator());
            }

            $player->teleport($this->getPlugin()->getArenaConfig()->getRandomSpawn($this));
        }

        parent::startGame();

        $this->getPlugin()->getScheduler()->scheduleRepeatingTask(new MatchTimeInfectionTask($this), 20);
    }

    /**
     * @return Player[]
     */
    public function getSurvivors(): array
    {
        return array_diff($this->getPlayers(false), $this->getInfected(), $this->getSpectators());
    }

    /**
     * @return Player[]
     */
    public function getInfected(): array
    {
        return $this->infected;
    }

    public function resetPlayer(Player $player): void
    {
        parent::resetPlayer($player);

        if ($this->isSpectator($player) && $player->getSkin() === $this->getInfectedSkin()) {
            $player->setSkin($this->getOriginalSkin($player));
            $player->sendSkin();
        }
    }

    public function isAlpha(Player $player): bool
    {
        return $this->getAlpha() === $player;
    }

    public function isInfected(Player $player): bool
    {
        return in_array($player, $this->infected, true);
    }

    public function getOriginalSkin(Player $player): Skin
    {
        return $this->skinData[$player->getName()];
    }

    public function assignChance(Player $player): void
    {
        if ($this->isInfected($player)) {
            $this->getPlugin()->getChanceHandler()->setPlayerChance($player, MMChance::INFECTED, 1);
        } else {
            $this->getPlugin()->getChanceHandler()->addPlayerChange($player, MMChance::INFECTED, mt_rand(1, 2));
        }
    }

    public function addParticipation(Player $player, array $data, bool $guildXP = false): void
    {
        if ($this->isWinner($player)) {
            if ($this->isAlpha($player)) {
                $data[self::DATA_CREDITS][] = [
                    'Win as Alpha',
                    5
                ];
            } elseif ($this->isInfected($player)) {
                $data[self::DATA_CREDITS][] = [
                    'Win as Infected',
                    4
                ];
            } else {
                $data[self::DATA_CREDITS][] = [
                    'Win as Innocent',
                    12
                ];
            }
        }

        parent::addParticipation($player, $data, $guildXP);
    }

    public function getStreaksKey(): ?string
    {
        if ($this->isPrivateGame()) return null;
        return strtolower($this->getPlugin()->getMinigameTag() . "_" . $this->getPlugin()->getModes()[$this->getModeId()]);
    }

    public function removeInfected(Player $player): void
    {
        $this->infected = array_diff($this->infected, [$player]);
    }

    final public function getWaitingPopup(Player $player): string
    {
        return '§cInfected chance:§6 ' . $this->getPlugin()->getChanceHandler()->getChancePercentage($this, $player, MMChance::INFECTED) . '%%';
    }

    public function getInfectedSkin(): Skin
    {
        return new Skin('Standard_Custom', base64_decode(''), '', 'geometry.humanoid.custom');
    }
}